// librarySourcePath builds the gate endpoint path for one library and plugin.
func librarySourcePath(libraryID int64, pluginID string) string {
	return fmt.Sprintf("/api/v1/libraries/%d/sources/%s", libraryID, pluginID)
}

// doLibraryGate runs a PUT or DELETE against the gate endpoint, asserting the
// 204 the endpoint answers on every accepted write (the write is its own
// acknowledgement — no body, no queued count).
func doLibraryGate(t *testing.T, h http.Handler, method string, libraryID int64, pluginID, body string) {
	t.Helper()
	resp := doRequest(t, h, method, librarySourcePath(libraryID, pluginID), body, adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusNoContent {
		t.Fatalf("%s status = %d, want %d", method, resp.StatusCode, http.StatusNoContent)
	}
}

// libraryPref returns the one library-scope gate row a PUT should have
// written, failing on absence or a wrong polarity.
func libraryPref(t *testing.T, st *store.Store, moduleID string, libraryID int64, pluginID string, wantEnabled bool) store.MetadataSourcePref {
	t.Helper()
	prefs, err := st.ListMetadataSourcePrefs(context.Background(), moduleID, []int64{libraryID})
	if err != nil {
		t.Fatalf("list prefs %s/%d: %v", moduleID, libraryID, err)
	}
	for _, p := range prefs {
		if p.LibraryID == libraryID && p.PluginID == pluginID {
			if p.Enabled != wantEnabled {
				t.Fatalf("pref = %+v, want Enabled=%v", p, wantEnabled)
			}
			return p
		}
	}
	t.Fatalf("no library-scope %s pref in %s/%d (rows: %+v)", pluginID, moduleID, libraryID, prefs)
	return store.MetadataSourcePref{}
}

// libraryResolves reads the effective per-library resolution GET /admin/sources
// reports for one library and plugin (through the real gate-resolution
// closures), asserting it equals want.
func libraryResolves(t *testing.T, h http.Handler, pluginID string, libraryID int64, want bool) {
	t.Helper()
	got := fetchAdminSources(t, h, "")
	src, ok := sourceByID(t, got, []string{"serial-parser", "shikimori", "tv-parser"})[pluginID]
	if !ok {
		t.Fatalf("plugin %s missing from the aggregate", pluginID)
	}
	enabled, ok := src.Effective.Libraries[fmt.Sprint(libraryID)]
	if !ok || enabled != want {
		t.Fatalf("%s library %d resolution = %v/%v, want %v", pluginID, libraryID, enabled, ok, want)
	}
}

